import React, { ReactNode } from "react";
import { UserProfile } from "../interfaces";
import Navigation from "../components/nav";
import { useTranslation } from "gatsby-plugin-react-i18next";
import { SiInstagram } from "react-icons/si";
import { ImFacebook2 } from "react-icons/im";
import {
  FaSquareFacebook,
  FaSquarePhone,
  FaSquareWhatsapp,
} from "react-icons/fa6";
import { MdEmail } from "react-icons/md";
import images from "../images";
import data from "../data/data.json";

interface LayoutProps {
  children: ReactNode;
  data?: UserProfile;
}

interface FooterData {
  copy: string;
}

const userData: UserProfile = data;

const Layout: React.FC<LayoutProps> = ({ children, data }) => {
  const { t } = useTranslation();
  const footerContent: { followUs: string; content: FooterData[] } = t(
    "footer",
    { returnObjects: true }
  ) || { followUs: "", content: [] };
  const currentYear = new Date().getFullYear();

  function formatPhoneNumber(phoneNumber: string) {
    const cleanedPhoneNumber = phoneNumber.replace(/\D+/g, "");
    if (cleanedPhoneNumber.startsWith("1")) {
      return `+1 ${cleanedPhoneNumber.slice(1, 4)} ${cleanedPhoneNumber.slice(
        4,
        7
      )} ${cleanedPhoneNumber.slice(7, 12)}`;
    } else {
      return cleanedPhoneNumber;
    }
  }

  return (
    <>
      <div
        className="fixed inset-0 bg-no-repeat bg-cover bg-center before:content-[''] before:absolute before:inset-0 before:bg-white/80"
      ></div>
      <div id={data?.menu[0]} className={styles.container}>
        <Navigation />
        <div className="relative">{children}</div>
      </div>

      <footer className={styles.footerContainer} id={userData.menu[4]}>
        <div className="flex flex-col sm:flex-row">
          <div className="flex flex-col rounded-2xl self-center w-full py-8">
            <img
              className="w-1/3 mx-auto shadow-2xl rounded-2xl"
              src={images.logo.src}
              alt={images.logo.src}
            />
          </div>

          <div className="flex flex-col w-full self-center">
            <a
              href={`mailto:${data?.email}`}
              className="flex flex-row gap-2 justify-center items-center text-lg sm:text-3xl font-bold"
            >
              <MdEmail />
              {data?.email}
            </a>
            <a
              href={`tel:${data?.phone}`}
              className="flex flex-row gap-2 justify-center items-center text-3xl font-bold"
            >
              <FaSquarePhone />
              {formatPhoneNumber(data?.phone || "")}
            </a>
            <div className="mx-auto p-4">
              &copy; {currentYear} {data?.name}
            </div>
          </div>

          <div className="flex flex-col self-center text-center w-full">
            <h3 className="mx-auto sm:mx-0 mt-4 sm:mt-0 text-xl">
              {t("footer.followUs")}
            </h3>
            <div className="flex mt-2 mx-auto justify-center sm:mx-0 gap-4">
              <a href={data?.instagram} target="_blank" rel="noreferrer">
                <SiInstagram className="text-terciary text-4xl" />
              </a>
              <a href={data?.facebook} target="_blank" rel="noreferrer">
                <ImFacebook2 className="text-terciary text-4xl" />
              </a>
            </div>
          </div>
        </div>
      </footer>
    </>
  );
};

export default Layout;

const styles = {
  container: "mx-auto",
  footerContainer: "flex flex-col bg-secondary text-light relative",
  logoContainer:
    "flex justify-center items-center shadow-2xl rounded-2xl relative",
};
